SELECT COUNT(*) n, COUNT(DISTINCT id) ids, COUNT(DISTINCT customer_id) custs, COUNT(DISTINCT status) statuses FROM orders_staging;
SELECT COUNT(*) FROM orders_staging s JOIN orders o ON s.id=o.id;
SELECT COUNT(*) FROM orders_staging s JOIN orders o ON s.id=o.id AND s.customer_id=o.customer_id;
SELECT customer_id, COUNT(*) c, COUNT(DISTINCT status) ds FROM orders_staging GROUP BY customer_id ORDER BY c DESC LIMIT 10;
SELECT COUNT(*) FROM orders WHERE customer_id IN (SELECT customer_id FROM orders_staging)

